import fs from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import {
    transcriptItems,
    windowTranscript,
    type TranscriptItem,
} from "../../../src/modules/decision/transcript";

/**
 * The state transcript is the probe's, so the probe pins it.
 *
 * `test/fixtures/transcript-window.json` is generated by running `.pi/local/reminder-transitions/session-midturn.py`
 * (`window_transcript`) over its own cached checkpoints - the reference implementation, not a copy. A case
 * here fails the moment the port drifts from what the measured variant actually sent.
 */

interface FixtureCase {
    session: string;
    turn: number;
    toolCalls: number;
    request: string;
    items: TranscriptItem[];
    rendered: Record<string, { text: string; chars: number; omitted: number }>;
}

const fixture = JSON.parse(
    fs.readFileSync(path.join(__dirname, "..", "..", "fixtures", "transcript-window.json"), "utf8"),
) as { cases: FixtureCase[] };

/** The fixture's labels as the arguments the port takes. */
const VARIANTS: Record<string, { elide: boolean; chars: number }> = {
    window800: { elide: false, chars: 800 },
    window1800: { elide: false, chars: 1800 },
    "window800-elided": { elide: true, chars: 800 },
    "window1800-elided": { elide: true, chars: 1800 },
};

describe("window transcript", () => {
    it("has fixture cases to pin", () => {
        expect(fixture.cases.length).toBeGreaterThan(0);
        expect(Object.keys(fixture.cases[0]?.rendered ?? {})).toEqual(Object.keys(VARIANTS));
    });

    for (const testCase of fixture.cases) {
        it(`matches the probe on ${testCase.session} turn ${String(testCase.turn)} cp ${String(testCase.toolCalls)}`, () => {
            for (const [label, options] of Object.entries(VARIANTS)) {
                const expected = testCase.rendered[label];
                const actual = windowTranscript(
                    testCase.items,
                    testCase.request,
                    options.elide,
                    options.chars,
                );

                expect(actual.text.length).toBe(expected?.chars);
                expect(actual.text).toBe(expected?.text);
            }
        });
    }

    it("turns the session's items into atoms, one phase marker per held phase", () => {
        const atoms = transcriptItems([
            { role: "user", text: "do it", turn: 1 },
            { role: "state", text: "  ── state: exploring ──", turn: 1 },
            { role: "state", text: "  ── state: exploring ──", turn: 1 },
            { role: "command", text: "npm test", turn: 1 },
            { role: "tool", text: "read(src/a.ts)", turn: 2 },
            { role: "assistant", text: "done", turn: 2 },
        ]);

        expect(atoms).toEqual([
            { kind: "user", text: "do it", turn: 1 },
            { kind: "marker", text: "  ── state: exploring ──", turn: 1 },
            { kind: "tool", name: "bash", arg: "npm test", turn: 1 },
            { kind: "tool", name: "read", arg: "src/a.ts", turn: 2 },
            { kind: "assistant", text: "done", turn: 2 },
        ]);

        // No turn stamped (a caller that did not walk the branch): everything reads as the newest turn.
        expect(transcriptItems([{ role: "tool", text: "ls(/repo)" }])).toEqual([
            { kind: "tool", name: "ls", arg: "/repo", turn: 0 },
        ]);
    });

    it("keeps the newest turn's tools and the earlier turns' messages", () => {
        const items: TranscriptItem[] = [
            { kind: "user", text: "first", turn: 1 },
            { kind: "tool", name: "read", arg: "a.ts", turn: 1 },
            { kind: "assistant", text: "read it", turn: 1 },
            { kind: "user", text: "second", turn: 2 },
            { kind: "tool", name: "edit", arg: "b.ts", turn: 2 },
        ];

        // Elision drops only tool items, and only from the turns before the newest.
        const elided = windowTranscript(items, "", true, 2000);
        expect(elided.text).toContain("User: first");
        expect(elided.text).toContain("Assistant: read it");
        expect(elided.text).toContain("Tool: edit(b.ts)");
    });

    it("appends the request when the window does not carry it", () => {
        const without = windowTranscript(
            [{ kind: "tool", name: "read", arg: "a.ts", turn: 1 }],
            "do the thing",
            false,
            800,
        );
        expect(without.text).toContain("User: do the thing");

        const with_ = windowTranscript(
            [
                { kind: "user", text: "do the thing", turn: 1 },
                { kind: "tool", name: "read", arg: "a.ts", turn: 1 },
            ],
            "do the thing",
            false,
            800,
        );
        expect(with_.text.match(/do the thing/gu)).toHaveLength(1);
    });
});
